/* Lorenz-Mie scattering from a homogeneous sphere.
 *
 * Direct port of mie.py (Bohren & Huffman conventions, exp(-i omega t),
 * m = n + ik with k >= 0, size parameter x = 2 pi n_med a / lambda_vac).
 *
 * The Python module is the ground truth; MIE.selfTest() checks this port
 * against reference values generated by crosscheck.py and embedded in the page.
 *
 * Complex numbers are carried as separate re/im scalars or paired Float64Arrays;
 * no allocation happens inside the hot loops.
 */
const MIE = (function () {
  'use strict';

  // Wiscombe truncation. Do NOT raise this: past ~nStop(x)+10 the upward
  // recurrence for the real Riccati-Bessel psi_n(rho) goes unstable (n >> rho).
  function nStop(x) {
    return Math.max(Math.floor(x + 4.0 * Math.cbrt(x) + 2.0) + 1, 4);
  }

  /* D_n(z) = psi'_n(z)/psi_n(z), downward recurrence (stable) */
  function logDeriv(zr, zi, nmx) {
    const Dr = new Float64Array(nmx + 1), Di = new Float64Array(nmx + 1);
    const den = zr * zr + zi * zi;
    for (let n = nmx; n >= 1; n--) {
      const nzr = n * zr / den, nzi = -n * zi / den;
      const tr = Dr[n] + nzr, ti = Di[n] + nzi;
      const td = tr * tr + ti * ti;
      Dr[n - 1] = nzr - tr / td;
      Di[n - 1] = nzi + ti / td;
    }
    return { Dr, Di };
  }

  /* psi_n(x), chi_n(x) for real x, upward recurrence */
  function riccatiReal(x, nmax) {
    const psi = new Float64Array(nmax + 1), chi = new Float64Array(nmax + 1);
    const psim1 = Math.cos(x), chim1 = -Math.sin(x);
    psi[0] = Math.sin(x); chi[0] = Math.cos(x);
    for (let n = 1; n <= nmax; n++) {
      const p2 = (n === 1) ? psim1 : psi[n - 2];
      const c2 = (n === 1) ? chim1 : chi[n - 2];
      psi[n] = (2 * n - 1) / x * psi[n - 1] - p2;
      chi[n] = (2 * n - 1) / x * chi[n - 1] - c2;
    }
    return { psi, chi };
  }

  /* j_n(w) for complex w via Miller's downward recurrence, per-point renormalised.
     Writes n = 0..nmax into jr/ji. tr/ti are scratch of length >= nstart+2. */
  function sphJnComplex(nmax, wr, wi, jr, ji, tr, ti) {
    const absw = Math.hypot(wr, wi);
    const nstart = nmax + Math.floor(absw) + 25;
    tr.fill(0, 0, nstart + 2); ti.fill(0, 0, nstart + 2);
    // Seed at 1.0, not at a tiny value: the recurrence grows downward, so a tiny
    // seed leaves t[0] denormal and |t[0]|^2 underflows to zero in the division below.
    tr[nstart] = 1.0;
    const wd = wr * wr + wi * wi;
    for (let n = nstart; n >= 1; n--) {
      const f = 2 * n + 1;
      const cr = f * wr / wd, ci = -f * wi / wd;
      const pr = cr * tr[n] - ci * ti[n], pi = cr * ti[n] + ci * tr[n];
      tr[n - 1] = pr - tr[n + 1];
      ti[n - 1] = pi - ti[n + 1];
      if (Math.abs(tr[n - 1]) + Math.abs(ti[n - 1]) > 1e200) {
        for (let k = n - 1; k <= nstart + 1; k++) { tr[k] *= 1e-200; ti[k] *= 1e-200; }
      }
    }
    // rescale so |t[0]| ~ 1, then the complex division is safe
    const s0 = Math.hypot(tr[0], ti[0]);
    for (let n = 0; n <= nmax; n++) { tr[n] /= s0; ti[n] /= s0; }
    // j_0(w) = sin(w)/w
    const sr = Math.sin(wr) * Math.cosh(wi), si = Math.cos(wr) * Math.sinh(wi);
    const j0r = (sr * wr + si * wi) / wd, j0i = (si * wr - sr * wi) / wd;
    const d0 = tr[0] * tr[0] + ti[0] * ti[0];
    const scr = (j0r * tr[0] + j0i * ti[0]) / d0, sci = (j0i * tr[0] - j0r * ti[0]) / d0;
    for (let n = 0; n <= nmax; n++) {
      jr[n] = tr[n] * scr - ti[n] * sci;
      ji[n] = tr[n] * sci + ti[n] * scr;
    }
  }

  /* scattering coefficients a_n, b_n */
  function mieAB(mr, mi, x, nmax) {
    nmax = nmax || nStop(x);
    const zr = mr * x, zi = mi * x;
    const nmx = Math.floor(Math.max(nmax, Math.hypot(zr, zi))) + 16;
    const { Dr, Di } = logDeriv(zr, zi, nmx);
    const { psi, chi } = riccatiReal(x, nmax);
    const ar = new Float64Array(nmax), ai = new Float64Array(nmax);
    const br = new Float64Array(nmax), bi = new Float64Array(nmax);
    const md = mr * mr + mi * mi;
    for (let n = 1; n <= nmax; n++) {
      const dmr = (Dr[n] * mr + Di[n] * mi) / md, dmi = (Di[n] * mr - Dr[n] * mi) / md;
      const tar = dmr + n / x, tai = dmi;
      const dMr = Dr[n] * mr - Di[n] * mi, dMi = Dr[n] * mi + Di[n] * mr;
      const tbr = dMr + n / x, tbi = dMi;
      const xr = psi[n], xm = -chi[n];
      const xr1 = psi[n - 1], xm1 = -chi[n - 1];

      let nr = tar * psi[n] - psi[n - 1], ni = tai * psi[n];
      let dr = tar * xr - tai * xm - xr1, di = tar * xm + tai * xr - xm1;
      let dd = dr * dr + di * di;
      ar[n - 1] = (nr * dr + ni * di) / dd; ai[n - 1] = (ni * dr - nr * di) / dd;

      nr = tbr * psi[n] - psi[n - 1]; ni = tbi * psi[n];
      dr = tbr * xr - tbi * xm - xr1; di = tbr * xm + tbi * xr - xm1;
      dd = dr * dr + di * di;
      br[n - 1] = (nr * dr + ni * di) / dd; bi[n - 1] = (ni * dr - nr * di) / dd;
    }
    return { ar, ai, br, bi, nmax };
  }

  /* internal-field coefficients c_n, d_n (numerator collapses to i*m by the Wronskian) */
  function mieCD(mr, mi, x, nmax) {
    const { psi, chi } = riccatiReal(x, nmax);
    const wr = mr * x, wi = mi * x;
    const jr = new Float64Array(nmax + 1), ji = new Float64Array(nmax + 1);
    const ns = nmax + Math.floor(Math.hypot(wr, wi)) + 27;
    sphJnComplex(nmax, wr, wi, jr, ji, new Float64Array(ns), new Float64Array(ns));

    const pr = new Float64Array(nmax + 1), pi = new Float64Array(nmax + 1);
    for (let n = 0; n <= nmax; n++) { pr[n] = wr * jr[n] - wi * ji[n]; pi[n] = wr * ji[n] + wi * jr[n]; }

    const cr = new Float64Array(nmax), ci = new Float64Array(nmax);
    const dr = new Float64Array(nmax), di = new Float64Array(nmax);
    const wd = wr * wr + wi * wi;
    const numr = -mi, numi = mr;                         // i*m
    for (let n = 1; n <= nmax; n++) {
      const xr = psi[n], xm = -chi[n];
      const xpr = psi[n - 1] - (n / x) * xr, xpi = -chi[n - 1] - (n / x) * xm;   // xi'_n(x)
      const nr = n * wr / wd, ni = -n * wi / wd;                                 // n/(mx)
      const tpr = nr * pr[n] - ni * pi[n], tpi = nr * pi[n] + ni * pr[n];
      const ppr = pr[n - 1] - tpr, ppi = pi[n - 1] - tpi;                        // psi'_n(mx)

      const Ar = pr[n] * xpr - pi[n] * xpi, Ai = pr[n] * xpi + pi[n] * xpr;
      const mxr = mr * xr - mi * xm, mxi = mr * xm + mi * xr;
      const Br = mxr * ppr - mxi * ppi, Bi = mxr * ppi + mxi * ppr;
      let dnr = Ar - Br, dni = Ai - Bi, dd = dnr * dnr + dni * dni;
      cr[n - 1] = (numr * dnr + numi * dni) / dd; ci[n - 1] = (numi * dnr - numr * dni) / dd;

      const mpr = mr * pr[n] - mi * pi[n], mpi = mr * pi[n] + mi * pr[n];
      const Cr = mpr * xpr - mpi * xpi, Ci = mpr * xpi + mpi * xpr;
      const Dr2 = xr * ppr - xm * ppi, Di2 = xr * ppi + xm * ppr;
      dnr = Cr - Dr2; dni = Ci - Di2; dd = dnr * dnr + dni * dni;
      dr[n - 1] = (numr * dnr + numi * dni) / dd; di[n - 1] = (numi * dnr - numr * dni) / dd;
    }
    return { cr, ci, dr, di };
  }

  function efficiencies(mr, mi, x) {
    const { ar, ai, br, bi, nmax } = mieAB(mr, mi, x);
    let qext = 0, qsca = 0, bkr = 0, bki = 0;
    for (let n = 1; n <= nmax; n++) {
      const t = 2 * n + 1, i = n - 1;
      qext += t * (ar[i] + br[i]);
      qsca += t * (ar[i] * ar[i] + ai[i] * ai[i] + br[i] * br[i] + bi[i] * bi[i]);
      const s = (n % 2 === 0) ? 1 : -1;
      bkr += t * s * (ar[i] - br[i]);
      bki += t * s * (ai[i] - bi[i]);
    }
    qext *= 2 / (x * x);
    qsca *= 2 / (x * x);
    const qback = (bkr * bkr + bki * bki) / (x * x);

    let t1 = 0, t2 = 0;
    for (let n = 1; n <= nmax - 1; n++) {
      const i = n - 1;
      const re = ar[i] * ar[i + 1] + ai[i] * ai[i + 1] + br[i] * br[i + 1] + bi[i] * bi[i + 1];
      t1 += n * (n + 2) / (n + 1) * re;
    }
    for (let n = 1; n <= nmax; n++) {
      const i = n - 1;
      t2 += (2 * n + 1) / (n * (n + 1)) * (ar[i] * br[i] + ai[i] * bi[i]);
    }
    const g = qsca > 0 ? (4 / (x * x)) * (t1 + t2) / qsca : 0;
    return { qext, qsca, qabs: qext - qsca, qback, g, nmax };
  }

  /* pi_n(mu), tau_n(mu) written into supplied buffers of length nmax+1 */
  function piTau(nmax, mu, pin, taun) {
    pin[0] = 0; taun[0] = 0;
    pin[1] = 1; taun[1] = mu;
    for (let n = 2; n <= nmax; n++) {
      pin[n] = ((2 * n - 1) / (n - 1)) * mu * pin[n - 1] - (n / (n - 1)) * pin[n - 2];
      taun[n] = n * mu * pin[n] - (n + 1) * pin[n - 1];
    }
  }

  /* S1(theta), S2(theta) for an array of angles */
  function amplitudes(mr, mi, x, thetas) {
    const { ar, ai, br, bi, nmax } = mieAB(mr, mi, x);
    const pin = new Float64Array(nmax + 1), taun = new Float64Array(nmax + 1);
    const n1 = thetas.length;
    const s1r = new Float64Array(n1), s1i = new Float64Array(n1);
    const s2r = new Float64Array(n1), s2i = new Float64Array(n1);
    for (let t = 0; t < n1; t++) {
      piTau(nmax, Math.cos(thetas[t]), pin, taun);
      let a1r = 0, a1i = 0, a2r = 0, a2i = 0;
      for (let n = 1; n <= nmax; n++) {
        const i = n - 1, w = (2 * n + 1) / (n * (n + 1));
        a1r += w * (ar[i] * pin[n] + br[i] * taun[n]);
        a1i += w * (ai[i] * pin[n] + bi[i] * taun[n]);
        a2r += w * (ar[i] * taun[n] + br[i] * pin[n]);
        a2i += w * (ai[i] * taun[n] + bi[i] * pin[n]);
      }
      s1r[t] = a1r; s1i[t] = a1i; s2r[t] = a2r; s2i[t] = a2i;
    }
    return { s1r, s1i, s2r, s2i };
  }

  /* dC_sca/dOmega in units of 1/k^2 */
  function dcs(s1r, s1i, s2r, s2i, phi, unpolarised) {
    const p1 = s1r * s1r + s1i * s1i, p2 = s2r * s2r + s2i * s2i;
    if (unpolarised) return 0.5 * (p1 + p2);
    const c = Math.cos(phi), s = Math.sin(phi);
    return p2 * c * c + p1 * s * s;
  }

  const INTERNAL_CUTOFF = 30.0;

  /* i^n * (2n+1)/(n(n+1)) */
  function EnRe(n) { const c = (2 * n + 1) / (n * (n + 1)); return (n % 4 === 0) ? c : (n % 4 === 2 ? -c : 0); }
  function EnIm(n) { const c = (2 * n + 1) / (n * (n + 1)); return (n % 4 === 1) ? c : (n % 4 === 3 ? -c : 0); }

  /* |E_total|^2 on a plane through the sphere centre, relative to the incident wave.
     Coordinates in units of the sphere radius. plane 'E' -> x-z, plane 'H' -> y-z.
     Returns { u, z, I } with I[iu*N + iz]. */
  function nearFieldSlice(mr, mi, x, halfExtent, N, plane) {
    const nmax = nStop(x);
    const { ar, ai, br, bi } = mieAB(mr, mi, x, nmax);
    const doInternal = Math.abs(mi) * x <= INTERNAL_CUTOFF;
    const cd = doInternal ? mieCD(mr, mi, x, nmax) : null;

    // premultiply the multipole weights
    const EaR = new Float64Array(nmax), EaI = new Float64Array(nmax);   // E_n * (i a_n)
    const EbR = new Float64Array(nmax), EbI = new Float64Array(nmax);   // E_n * b_n
    const EcR = new Float64Array(nmax), EcI = new Float64Array(nmax);   // E_n * c_n
    const EdR = new Float64Array(nmax), EdI = new Float64Array(nmax);   // E_n * (-i d_n)
    for (let n = 1; n <= nmax; n++) {
      const i = n - 1, er = EnRe(n), ei = EnIm(n);
      const iar = -ai[i], iai = ar[i];                                  // i*a_n
      EaR[i] = er * iar - ei * iai; EaI[i] = er * iai + ei * iar;
      EbR[i] = er * br[i] - ei * bi[i]; EbI[i] = er * bi[i] + ei * br[i];
      if (doInternal) {
        const idr = cd.di[i], idi = -cd.dr[i];                          // -i*d_n
        EcR[i] = er * cd.cr[i] - ei * cd.ci[i]; EcI[i] = er * cd.ci[i] + ei * cd.cr[i];
        EdR[i] = er * idr - ei * idi; EdI[i] = er * idi + ei * idr;
      }
    }

    const u = new Float64Array(N), zc = new Float64Array(N);
    for (let i = 0; i < N; i++) {
      u[i] = -halfExtent + 2 * halfExtent * i / (N - 1);
      zc[i] = u[i];
    }

    const I = new Float64Array(N * N);
    const pin = new Float64Array(nmax + 1), taun = new Float64Array(nmax + 1);
    const psi = new Float64Array(nmax + 1), chi = new Float64Array(nmax + 1);
    const jr = new Float64Array(nmax + 1), ji = new Float64Array(nmax + 1);
    const ns = nmax + Math.floor(Math.hypot(mr, mi) * x) + 27;
    const scr = new Float64Array(ns + 2), sci = new Float64Array(ns + 2);

    for (let iu = 0; iu < N; iu++) {
      const uu = u[iu];
      const sgn = uu >= 0 ? 1 : -1;
      const cf = (plane === 'E') ? sgn : 0;
      const sf = (plane === 'E') ? 0 : sgn;
      for (let iz = 0; iz < N; iz++) {
        const zz = zc[iz];
        // theta from the raw coordinates, r clamped separately. Deriving ct = z/r
        // after clamping breaks at the exact origin: it yields ct = st = 0, which is
        // not a direction at all. atan2(0,0) = 0 picks the +z limit, as mie.py does.
        const theta = Math.atan2(Math.abs(uu), zz);
        const ct = Math.cos(theta), st = Math.sin(theta);
        let r = Math.hypot(uu, zz);
        if (r < 1e-4) r = 1e-4;
        piTau(nmax, ct, pin, taun);

        let err = 0, eri = 0, etr = 0, eti = 0, epr = 0, epi = 0;

        if (r >= 1.0) {
          const rho = x * r;
          psi[0] = Math.sin(rho); chi[0] = Math.cos(rho);
          const pm1 = Math.cos(rho), cm1 = -Math.sin(rho);
          for (let n = 1; n <= nmax; n++) {
            const p2 = (n === 1) ? pm1 : psi[n - 2];
            const c2 = (n === 1) ? cm1 : chi[n - 2];
            psi[n] = (2 * n - 1) / rho * psi[n - 1] - p2;
            chi[n] = (2 * n - 1) / rho * chi[n - 1] - c2;
          }
          for (let n = 1; n <= nmax; n++) {
            const i = n - 1;
            const xr = psi[n], xm = -chi[n];                       // xi_n
            const hr = xr / rho, hi = xm / rho;                    // h_n
            const dxr = psi[n - 1] - (n / rho) * xr;
            const dxi = -chi[n - 1] - (n / rho) * xm;              // xi'_n
            const gr = dxr / rho, gi = dxi / rho;                  // [rho h_n]'/rho

            const wr_ = cf * n * (n + 1) * st * pin[n] / rho;
            err += EaR[i] * hr * wr_ - EaI[i] * hi * wr_;
            eri += EaR[i] * hi * wr_ + EaI[i] * hr * wr_;

            const w1 = cf * taun[n], w2 = cf * pin[n];
            etr += (EaR[i] * gr - EaI[i] * gi) * w1 - (EbR[i] * hr - EbI[i] * hi) * w2;
            eti += (EaR[i] * gi + EaI[i] * gr) * w1 - (EbR[i] * hi + EbI[i] * hr) * w2;

            const w3 = sf * pin[n], w4 = sf * taun[n];
            epr += -(EaR[i] * gr - EaI[i] * gi) * w3 + (EbR[i] * hr - EbI[i] * hi) * w4;
            epi += -(EaR[i] * gi + EaI[i] * gr) * w3 + (EbR[i] * hi + EbI[i] * hr) * w4;
          }
          // incident plane wave exp(i x z) x_hat on the spherical basis
          const ph = x * zz, cp = Math.cos(ph), sp = Math.sin(ph);
          err += cp * st * cf; eri += sp * st * cf;
          etr += cp * ct * cf; eti += sp * ct * cf;
          epr += -cp * sf; epi += -sp * sf;
        } else if (doInternal) {
          const wr = mr * x * r, wi = mi * x * r;
          sphJnComplex(nmax, wr, wi, jr, ji, scr, sci);
          const wd = wr * wr + wi * wi;
          for (let n = 1; n <= nmax; n++) {
            const i = n - 1;
            const pr = wr * jr[n] - wi * ji[n], pi_ = wr * ji[n] + wi * jr[n];       // psi_n(w)
            const pr1 = wr * jr[n - 1] - wi * ji[n - 1], pi1 = wr * ji[n - 1] + wi * jr[n - 1];
            const nr = n * wr / wd, ni = -n * wi / wd;                                // n/w
            const tpr = nr * pr - ni * pi_, tpi = nr * pi_ + ni * pr;
            const dpr = pr1 - tpr, dpi = pi1 - tpi;                                   // psi'_n(w)
            const gr = (dpr * wr + dpi * wi) / wd, gi = (dpi * wr - dpr * wi) / wd;   // psi'_n/w
            const qr = (jr[n] * wr + ji[n] * wi) / wd, qi = (ji[n] * wr - jr[n] * wi) / wd; // j_n/w

            const wr_ = cf * n * (n + 1) * st * pin[n];
            err += (EdR[i] * qr - EdI[i] * qi) * wr_;
            eri += (EdR[i] * qi + EdI[i] * qr) * wr_;

            const w1 = cf * pin[n], w2 = cf * taun[n];
            etr += (EcR[i] * jr[n] - EcI[i] * ji[n]) * w1 + (EdR[i] * gr - EdI[i] * gi) * w2;
            eti += (EcR[i] * ji[n] + EcI[i] * jr[n]) * w1 + (EdR[i] * gi + EdI[i] * gr) * w2;

            const w3 = sf * taun[n], w4 = sf * pin[n];
            epr += -(EcR[i] * jr[n] - EcI[i] * ji[n]) * w3 - (EdR[i] * gr - EdI[i] * gi) * w4;
            epi += -(EcR[i] * ji[n] + EcI[i] * jr[n]) * w3 - (EdR[i] * gi + EdI[i] * gr) * w4;
          }
        }

        I[iu * N + iz] = err * err + eri * eri + etr * etr + eti * eti + epr * epr + epi * epi;
      }
    }
    return { u, z: zc, I, N };
  }

  /* -------- self-test against the Python reference embedded in the page -------- */
  function selfTest(ref) {
    const TOL = 1e-9;
    const out = [];
    let worst = 0;

    // A non-finite error must fail loudly rather than poison Math.max silently.
    const bump = (err, msg) => {
      if (!isFinite(err)) { worst = Infinity; out.push(msg + ' [non-finite]'); return; }
      worst = Math.max(worst, err);
      if (err > TOL) out.push(msg + ` err=${err.toExponential(2)}`);
    };

    for (const c of ref.cases) {
      const e = efficiencies(c.mr, c.mi, c.x);
      // each quantity judged on its own natural scale: qabs is legitimately 0 for a
      // non-absorbing sphere, so it is compared against qext, not against itself
      const den = {
        qext: Math.abs(c.qext),
        qsca: Math.abs(c.qsca),
        qabs: Math.abs(c.qext),
        qback: Math.max(Math.abs(c.qback), 1e-6 * Math.abs(c.qsca)),
        g: Math.max(Math.abs(c.g), 1e-2)
      };
      for (const k of ['qext', 'qsca', 'qabs', 'qback', 'g']) {
        bump(Math.abs(e[k] - c[k]) / den[k], `${c.name} ${k}:`);
      }

      const th = Float64Array.from(c.theta);
      const A = amplitudes(c.mr, c.mi, c.x, th);
      let sm = 0;
      for (let i = 0; i < th.length; i++) sm = Math.max(sm, Math.abs(c.s1abs[i]), Math.abs(c.s2abs[i]));
      for (let i = 0; i < th.length; i++) {
        const a1 = Math.hypot(A.s1r[i], A.s1i[i]), a2 = Math.hypot(A.s2r[i], A.s2i[i]);
        bump(Math.max(Math.abs(a1 - c.s1abs[i]), Math.abs(a2 - c.s2abs[i])) / sm,
             `${c.name} S(theta=${th[i].toFixed(3)}):`);
      }
    }

    for (const nf of ref.nearfield) {
      const r = nearFieldSlice(nf.mr, nf.mi, nf.x, nf.halfExtent, nf.N, nf.plane);
      let mx = 0;
      for (let i = 0; i < nf.I.length; i++) mx = Math.max(mx, nf.I[i]);
      let e = 0;
      for (let i = 0; i < nf.I.length; i++) {
        if (!isFinite(r.I[i])) { e = Infinity; break; }
        e = Math.max(e, Math.abs(r.I[i] - nf.I[i]) / mx);
      }
      bump(e, `${nf.name} nearfield |E|^2 (${nf.plane}-plane):`);
    }
    return { pass: worst <= TOL, worst, failures: out };
  }

  return { nStop, mieAB, mieCD, efficiencies, amplitudes, dcs, nearFieldSlice, selfTest,
           sphJnComplex, riccatiReal, piTau };
})();
